FILE = "03-02-descriptive-diagnostic.vi.md"
PAIRS = [
("""Phép so sánh hai mẫu số cho thấy tỷ lệ nào phụ thuộc vào cách xác định phạm vi dữ liệu; đây là nguyên nhân chính khiến một tỷ lệ mô tả có thể gây hiểu sai.""",
 """Phép so sánh hai mẫu số cho thấy những tỷ lệ nào phụ thuộc vào cách xác định phạm vi dữ liệu. Cách xác định phạm vi dữ liệu chính là nguồn chủ yếu khiến một tỷ lệ mô tả có thể gây hiểu sai."""),
("""AQ2 hỏi sinh viên có một dấu hiệu tính đến hết ngày 27 không hoàn thành thường xuyên hơn bao nhiêu so với sinh viên tương đương không có dấu hiệu đó.""",
 """AQ2 hỏi: so với sinh viên tương đương không có dấu hiệu, sinh viên có một dấu hiệu tính đến hết ngày 27 có tỷ lệ không hoàn thành cao hơn bao nhiêu?"""),
("""Mô hình này có hiệu ứng cố định cho từng kỳ mở module để chỉ so sánh sinh viên trong cùng một kỳ mở, có hiệu chỉnh theo số lần học trước và số tín chỉ đang học, cùng các số hạng tương tác dấu hiệu × module để độ lớn mối liên hệ của một dấu hiệu được phép khác nhau giữa các module.""",
 """Mô hình này có hiệu ứng cố định cho từng kỳ mở module, nhờ đó chỉ so sánh sinh viên trong cùng một kỳ mở. Ngoài ra, mô hình hiệu chỉnh theo số lần học trước và số tín chỉ đang học. Các số hạng tương tác dấu hiệu × module cho phép độ lớn mối liên hệ của một dấu hiệu khác nhau giữa các module."""),
("""**AQ2: lý do chọn mô hình này.** Hiệu ứng cố định phù hợp với thiết kế trong đó mọi kỳ mở của các module được nghiên cứu đều có trong dữ liệu; còn việc có tính sai số chuẩn theo cụm hay không phụ thuộc vào cách dữ liệu được lấy mẫu, không chỉ vào cách phân nhóm [12]. Mô hình hiệu ứng hỗn hợp, vốn coi các module là một mẫu lấy từ một tổng thể lớn hơn, không được chọn, vì 6 module và 9 kỳ mở huấn luyện là quá ít để ước lượng phương sai giữa các module. Hiệu ứng được báo cáo là chênh lệch nguy cơ trung bình tính bằng điểm phần trăm, kèm tỉ số odds. Trong dữ liệu này, 44–46% sinh viên không hoàn thành, tức là biến kết quả phổ biến, nên tỉ số odds lớn hơn tỉ số nguy cơ; ngoài ra, giá trị p không đo độ lớn hay tầm quan trọng của một hiệu ứng [13]. Các dấu hiệu tương quan với nhau, nên các ước lượng đã hiệu chỉnh lẫn nhau là hiệu ứng riêng phần; báo cáo trình bày các ước lượng này cạnh các chênh lệch chưa hiệu chỉnh, không diễn giải thành trọng số riêng của từng dấu hiệu. Xét theo các tiêu chí còn lại, mô hình giả định rằng trong một module, các dấu hiệu cộng dồn trên thang log-odds; các số hạng dấu hiệu × module nới lỏng giả định này. Mô hình phù hợp với dữ liệu, vì ngay cả kỳ mở huấn luyện nhỏ nhất cũng có 369 lượt đăng ký học với 91 sinh viên không hoàn thành. Mô hình cho kết quả tất định, được kiểm tra bằng sai số chuẩn vững và các lần chạy phân tích độ nhạy, đồng thời không dùng thuộc tính nhạy cảm nào làm dấu hiệu.""",
 """**AQ2: lập luận cho mô hình này.** Hiệu ứng cố định phù hợp với thiết kế trong đó mọi kỳ mở của các module được nghiên cứu đều có trong dữ liệu. Việc có tính sai số chuẩn theo cụm hay không phụ thuộc vào cách dữ liệu được lấy mẫu, chứ không chỉ vào cách dữ liệu được chia nhóm [12]. Ở đây, mọi kỳ mở đều được quan sát đầy đủ chứ không phải được lấy mẫu, nên mô hình dùng sai số chuẩn vững và không tính sai số chuẩn theo cụm. Mô hình hiệu ứng hỗn hợp coi các module là một mẫu lấy từ một tổng thể lớn hơn; nhóm tác giả không chọn mô hình này, vì 6 module và 9 kỳ mở huấn luyện là quá ít để ước lượng phương sai giữa các module.

Hiệu ứng được báo cáo là chênh lệch nguy cơ trung bình tính bằng điểm phần trăm, kèm tỉ số odds. Khi biến kết quả phổ biến, tỉ số odds cho thấy hiệu ứng lớn hơn so với tỉ số nguy cơ; trong dữ liệu này, 44–46% sinh viên không hoàn thành, nên cần lưu ý điều đó. Bên cạnh đó, giá trị p không đo độ lớn hay tầm quan trọng của một hiệu ứng [13]. Các dấu hiệu tương quan với nhau, nên trong mô hình, ước lượng của mỗi dấu hiệu đã được hiệu chỉnh theo các dấu hiệu còn lại. Các ước lượng đã hiệu chỉnh lẫn nhau này gọi là hiệu ứng riêng phần. Mỗi hiệu ứng riêng phần cho thấy chênh lệch gắn với một dấu hiệu khi các dấu hiệu khác được giữ như nhau. Chênh lệch này nhỏ hơn chênh lệch mà dấu hiệu đó cho thấy khi xét riêng, và không phải là phần tình trạng không hoàn thành do dấu hiệu đó giải thích. Vì vậy, báo cáo trình bày hai loại chênh lệch cạnh nhau.

Mô hình cũng đáp ứng các tiêu chí còn lại trong tám tiêu chí của Mục 3.1. Về giả định, mô hình coi phần đóng góp của các dấu hiệu trong một module là cộng được với nhau trên thang log-odds; các số hạng dấu hiệu × module nới lỏng giả định này. Về mức phù hợp với dữ liệu, ngay cả kỳ mở huấn luyện nhỏ nhất cũng có 369 lượt đăng ký học với 91 sinh viên không hoàn thành. Về tính bền vững, mô hình cho kết quả tất định và được kiểm tra bằng sai số chuẩn vững cùng các lần chạy phân tích độ nhạy. Cuối cùng, mô hình không dùng thuộc tính nhạy cảm nào làm dấu hiệu."""),
("""**AQ2: dữ liệu sử dụng.** AQ2 được ước lượng trên 9 kỳ mở năm 2013 và chỉ được lặp lại trên 13 kỳ mở năm 2014 sau lần kiểm tra của AQ3 (C14), để không kết quả nào của tập kiểm thử được nhìn thấy trong lúc chọn mô hình dự báo. Phụ lục I (Bảng A.1) đối chiếu các phương pháp ứng viên cho AQ2 với tám tiêu chí, theo từng ô của bảng.""",
 """**AQ2: dữ liệu sử dụng.** AQ2 được ước lượng trên 9 kỳ mở năm 2013. Phép ước lượng này chỉ được lặp lại trên 13 kỳ mở năm 2014 sau khi mô hình AQ3 đã qua lần kiểm tra trên tập kiểm thử (C14); nhờ vậy, khi chọn mô hình dự báo, nhóm tác giả chưa thấy kết quả nào của tập kiểm thử. Phụ lục I (Bảng A.1) đối chiếu chi tiết các phương pháp ứng viên cho AQ2 với tám tiêu chí."""),
]
